// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;

    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address ownerArg, address collateralArg) public {
        // owner and collateral must differ so the two offsets are distinguishable
        vm.assume(ownerArg != collateralArg);
        vm.assume(uint256(uint160(ownerArg)) != 0);

        // Build clone-style calldata: selector ++ immutable args ++ 2-byte length.
        // args region: 20 bytes owner (at offset 0x00) ++ 20 bytes collateral (at offset 0x14)
        bytes memory args = abi.encodePacked(
            abi.encodeWithSelector(Cooler.owner.selector),
            bytes20(ownerArg),
            bytes20(collateralArg),
            uint16(40) // args length appended at end, as ClonesWithImmutableArgs does
        );

        (bool ok, bytes memory ret) = address(c).call(args);
        assertTrue(ok);

        address returned = abi.decode(ret, (address));

        // General rule: owner() always returns the immutable arg at offset 0x0
        assertTrue(returned == ownerArg);
    }
}
